[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Leap Studio — Your Reinvention and Experience Partner</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    :root {
      --bg-base: oklch(5% 0.005 265);
      --bg-surface: oklch(11% 0.008 265);
      --bg-elevated: oklch(15% 0.01 265);
      --text-primary: oklch(96% 0.008 265);
      --text-secondary: oklch(70% 0.015 265);
      --text-muted: oklch(50% 0.02 265);
      --accent-blue: oklch(65% 0.2 265);
      --accent-amber: oklch(75% 0.16 50);
      --accent-blue-muted: oklch(55% 0.15 265);
      --border: oklch(20% 0.015 265);
      --border-light: oklch(16% 0.01 265);
      --space-1: 4px;
      --space-2: 8px;
      --space-3: 16px;
      --space-4: 24px;
      --space-5: 32px;
      --space-6: 48px;
      --space-7: 64px;
      --space-8: 96px;
      --radius-sm: 6px;
      --radius-md: 12px;
      --radius-lg: 20px;
      --font-sans: 'Inter', system-ui, sans-serif;
      --transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1);
    }

    html {
      scroll-behavior: smooth;
    }

    body {
      font-family: var(--font-sans);
      background: #0A0A0A;
      color: var(--text-primary);
      line-height: 1.6;
      overflow-x: hidden;
      -webkit-font-smoothing: antialiased;
    }

    a {
      color: inherit;
      text-decoration: none;
    }

    img {
      max-width: 100%;
      display: block;
    }

    .container {
      max-width: 1280px;
      margin: 0 auto;
      padding: 0 var(--space-5);
    }

    /* ============ NAVIGATION ============ */
    .nav {
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      z-index: 100;
      background: rgba(10, 10, 10, 0.85);
      backdrop-filter: blur(20px);
      border-bottom: 1px solid var(--border-light);
    }

    .nav-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 72px;
      padding: 0 var(--space-5);
      max-width: 1400px;
      margin: 0 auto;
    }

    .nav-logo {
      font-size: 20px;
      font-weight: 800;
      letter-spacing: -0.5px;
    }

    .nav-logo span {
      color: var(--accent-blue);
    }

    .nav-links {
      display: none;
      gap: var(--space-5);
      list-style: none;
    }

    .nav-links a {
      font-size: 14px;
      font-weight: 500;
      color: var(--text-secondary);
      transition: color var(--transition);
      position: relative;
    }

    .nav-links a::after {
      content: '';
      position: absolute;
      bottom: -4px;
      left: 0;
      width: 0;
      height: 1px;
      background: var(--accent-blue);
      transition: width var(--transition);
    }

    .nav-links a:hover {
      color: var(--text-primary);
    }

    .nav-links a:hover::after {
      width: 100%;
    }

    .nav-right {
      display: flex;
      align-items: center;
      gap: var(--space-4);
    }

    .lang-selector {
      position: relative;
    }

    .lang-btn {
      display: flex;
      align-items: center;
      gap: var(--space-2);
      background: transparent;
      border: 1px solid var(--border);
      color: var(--text-secondary);
      padding: 8px 14px;
      border-radius: var(--radius-sm);
      font-size: 13px;
      font-weight: 500;
      cursor: pointer;
      transition: all var(--transition);
    }

    .lang-btn:hover {
      border-color: var(--accent-blue);
      color: var(--text-primary);
    }

    .lang-btn svg {
      width: 14px;
      height: 14px;
      transition: transform var(--transition);
    }

    .lang-dropdown {
      position: absolute;
      top: calc(100% + 8px);
      right: 0;
      background: var(--bg-elevated);
      border: 1px solid var(--border);
      border-radius: var(--radius-md);
      padding: var(--space-2);
      min-width: 160px;
      opacity: 0;
      visibility: hidden;
      transform: translateY(-8px);
      transition: all var(--transition);
      box-shadow: 0 20px 40px rgba(0,0,0,0.5);
    }

    .lang-dropdown.active {
      opacity: 1;
      visibility: visible;
      transform: translateY(0);
    }

    .lang-option {
      display: block;
      padding: 10px 14px;
      border-radius: var(--radius-sm);
      font-size: 13px;
      color: var(--text-secondary);
      cursor: pointer;
      transition: all var(--transition);
    }

    .lang-option:hover {
      background: var(--bg-surface);
      color: var(--text-primary);
    }

    .lang-option.active {
      color: var(--accent-blue);
    }

    .hamburger {
      display: flex;
      flex-direction: column;
      gap: 5px;
      background: none;
      border: none;
      cursor: pointer;
      padding: 8px;
    }

    .hamburger span {
      width: 22px;
      height: 2px;
      background: var(--text-primary);
      border-radius: 2px;
      transition: all var(--transition);
    }

    .mobile-menu {
      display: none;
      position: fixed;
      top: 72px;
      left: 0;
      right: 0;
      background: var(--bg-base);
      border-bottom: 1px solid var(--border);
      padding: var(--space-4) var(--space-5);
    }

    .mobile-menu.active {
      display: block;
    }

    .mobile-menu a {
      display: block;
      padding: var(--space-3) 0;
      font-size: 16px;
      font-weight: 500;
      color: var(--text-secondary);
      border-bottom: 1px solid var(--border-light);
    }

    .mobile-menu a:last-child {
      border-bottom: none;
    }

    @media (min-width: 1024px) {
      .nav-links {
        display: flex;
      }
      .hamburger {
        display: none;
      }
    }

    /* ============ HERO CAROUSEL ============ */
    .hero {
      min-height: 100vh;
      display: flex;
      align-items: center;
      padding-top: 72px;
      position: relative;
      overflow: hidden;
    }

    .hero-bg {
      position: absolute;
      inset: 0;
      background: radial-gradient(ellipse at 20% 50%, rgba(79, 143, 255, 0.08) 0%, transparent 50%),
                  radial-gradient(ellipse at 80% 80%, rgba(255, 179, 71, 0.05) 0%, transparent 40%);
    }

    .hero-inner {
      position: relative;
      z-index: 1;
      width: 100%;
    }

    .hero-carousel {
      position: relative;
      overflow: hidden;
    }

    .hero-track {
      display: flex;
      transition: transform 0.6s cubic-bezier(0.4, 0, 0.2, 1);
    }

    .hero-slide {
      flex: 0 0 100%;
      padding: var(--space-6) 0;
    }

    .hero-content {
      max-width: 800px;
    }

    .hero-tag {
      display: inline-flex;
      align-items: center;
      gap: var(--space-2);
      background: var(--bg-elevated);
      border: 1px solid var(--border);
      padding: 6px 14px;
      border-radius: 100px;
      font-size: 12px;
      font-weight: 600;
      color: var(--accent-blue);
      text-transform: uppercase;
      letter-spacing: 0.5px;
      margin-bottom: var(--space-5);
    }

    .hero-title {
      font-size: clamp(36px, 6vw, 72px);
      font-weight: 800;
      line-height: 1.05;
      letter-spacing: -2px;
      margin-bottom: var(--space-4);
    }

    .hero-desc {
      font-size: 18px;
      color: var(--text-secondary);
      max-width: 560px;
      margin-bottom: var(--space-6);
      line-height: 1.7;
    }

    .hero-cta {
      display: inline-flex;
      align-items: center;
      gap: var(--space-3);
      background: var(--accent-blue);
      color: #fff;
      padding: 14px 28px;
      border-radius: var(--radius-sm);
      font-size: 15px;
      font-weight: 600;
      transition: all var(--transition);
      border: none;
      cursor: pointer;
    }

    .hero-cta:hover {
      background: var(--accent-blue-muted);
      transform: translateY(-2px);
      box-shadow: 0 10px 30px rgba(79, 143, 255, 0.3);
    }

    .hero-nav {
      display: flex;
      align-items: center;
      gap: var(--space-4);
      margin-top: var(--space-6);
    }

    .hero-dots {
      display: flex;
      gap: var(--space-2);
    }

    .hero-dot {
      width: 8px;
      height: 8px;
      border-radius: 50%;
      background: var(--border);
      border: none;
      cursor: pointer;
      transition: all var(--transition);
    }

    .hero-dot.active {
      width: 32px;
      border-radius: 4px;
      background: var(--accent-blue);
    }

    .hero-arrow {
      width: 44px;
      height: 44px;
      border-radius: 50%;
      border: 1px solid var(--border);
      background: transparent;
      color: var(--text-primary);
      cursor: pointer;
      display: flex;
      align-items: center;
      justify-content: center;
      transition: all var(--transition);
    }

    .hero-arrow:hover {
      border-color: var(--accent-blue);
      background: var(--accent-blue);
      color: #fff;
    }

    .hero-arrow svg {
      width: 18px;
      height: 18px;
    }

    /* ============ TEAM SECTION ============ */
    .team {
      padding: var(--space-8) 0;
      background: var(--bg-base);
      border-top: 1px solid var(--border-light);
    }

    .section-header {
      text-align: center;
      margin-bottom: var(--space-7);
    }

    .section-tag {
      display: inline-block;
      font-size: 12px;
      font-weight: 600;
      color: var(--accent-blue);
      text-transform: uppercase;
      letter-spacing: 1.5px;
      margin-bottom: var(--space-3);
    }

    .section-title {
      font-size: clamp(32px, 5vw, 56px);
      font-weight: 800;
      letter-spacing: -1.5px;
      margin-bottom: var(--space-3);
    }

    .section-subtitle {
      font-size: 18px;
      color: var(--text-secondary);
      max-width: 600px;
      margin: 0 auto;
    }

    .region-tabs {
      display: flex;
      justify-content: center;
      gap: var(--space-2);
      margin-bottom: var(--space-6);
      flex-wrap: wrap;
    }

    .region-tab {
      padding: 10px 20px;
      background: transparent;
      border: 1px solid var(--border);
      border-radius: 100px;
      color: var(--text-secondary);
      font-size: 14px;
      font-weight: 500;
      cursor: pointer;
      transition: all var(--transition);
    }

    .region-tab:hover {
      border-color: var(--text-muted);
      color: var(--text-primary);
    }

    .region-tab.active {
      background: var(--accent-blue);
      border-color: var(--accent-blue);
      color: #fff;
    }

    .team-carousel-wrapper {
      position: relative;
      overflow: hidden;
    }

    .team-track {
      display: flex;
      gap: var(--space-4);
      transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
    }

    .team-card {
      flex: 0 0 340px;
      background: var(--bg-surface);
      border: 1px solid var(--border-light);
      border-radius: var(--radius-lg);
      overflow: hidden;
      transition: all var(--transition);
    }

    .team-card:hover {
      border-color: var(--accent-blue);
      transform: translateY(-4px);
      box-shadow: 0 20px 40px rgba(0,0,0,0.3);
    }

    .team-card-image {
      aspect-ratio: 4/3;
      background: var(--bg-elevated);
      overflow: hidden;
    }

    .team-card-image img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      filter: grayscale(20%) brightness(0.9);
      transition: all var(--transition);
    }

    .team-card:hover .team-card-image img {
      filter: grayscale(0%) brightness(1);
      transform: scale(1.05);
    }

    .team-card-body {
      padding: var(--space-5);
    }

    .team-card-quote {
      font-size: 14px;
      font-style: italic;
      color: var(--text-secondary);
      line-height: 1.7;
      margin-bottom: var(--space-4);
      position: relative;
      padding-left: var(--space-4);
    }

    .team-card-quote::before {
      content: '"';
      position: absolute;
      left: 0;
      top: -4px;
      font-size: 32px;
      color: var(--accent-blue);
      font-family: Georgia, serif;
    }

    .team-card-name {
      font-size: 16px;
      font-weight: 700;
      margin-bottom: var(--space-1);
    }

    .team-card-title {
      font-size: 13px;
      color: var(--text-muted);
      margin-bottom: var(--space-3);
    }

    .team-card-contact {
      display: inline-flex;
      align-items: center;
      gap: var(--space-2);
      font-size: 13px;
      font-weight: 600;
      color: var(--accent-blue);
      transition: gap var(--transition);
    }

    .team-card-contact:hover {
      gap: var(--space-3);
    }

    .team-card-contact svg {
      width: 14px;
      height: 14px;
    }

    .team-nav {
      display: flex;
      justify-content: center;
      gap: var(--space-3);
      margin-top: var(--space-6);
    }

    .team-arrow {
      width: 48px;
      height: 48px;
      border-radius: 50%;
      border: 1px solid var(--border);
      background: transparent;
      color: var(--text-primary);
      cursor: pointer;
      display: flex;
      align-items: center;
      justify-content: center;
      transition: all var(--transition);
    }

    .team-arrow:hover:not(:disabled) {
      border-color: var(--accent-blue);
      background: var(--accent-blue);
      color: #fff;
    }

    .team-arrow:disabled {
      opacity: 0.3;
      cursor: not-allowed;
    }

    .team-arrow svg {
      width: 20px;
      height: 20px;
    }

    /* ============ WORK SECTION ============ */
    .work {
      padding: var(--space-8) 0;
      background: #080808;
      border-top: 1px solid var(--border-light);
      overflow: hidden;
    }

    .work-carousel-wrapper {
      position: relative;
    }

    .work-track {
      display: flex;
      gap: var(--space-5);
      padding: var(--space-4) 0;
      overflow-x: auto;
      scroll-snap-type: x mandatory;
      scrollbar-width: none;
      -ms-overflow-style: none;
      -webkit-overflow-scrolling: touch;
    }

    .work-track::-webkit-scrollbar {
      display: none;
    }

    .work-card {
      flex: 0 0 380px;
      scroll-snap-align: start;
      background: var(--bg-surface);
      border: 1px solid var(--border-light);
      border-radius: var(--radius-lg);
      overflow: hidden;
      transition: all var(--transition);
    }

    .work-card:hover {
      border-color: var(--accent-amber);
      transform: translateY(-4px);
      box-shadow: 0 20px 40px rgba(0,0,0,0.4);
    }

    .work-card-image {
      aspect-ratio: 16/10;
      background: var(--bg-elevated);
      overflow: hidden;
      position: relative;
    }

    .work-card-image img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      transition: transform var(--transition);
    }

    .work-card:hover .work-card-image img {
      transform: scale(1.05);
    }

    .work-card-badge {
      position: absolute;
      top: var(--space-3);
      left: var(--space-3);
      background: rgba(0,0,0,0.7);
      backdrop-filter: blur(8px);
      padding: 4px 10px;
      border-radius: 100px;
      font-size: 11px;
      font-weight: 600;
      color: var(--text-primary);
      text-transform: uppercase;
      letter-spacing: 0.5px;
    }

    .work-card-body {
      padding: var(--space-5);
    }

    .work-card-client {
      font-size: 12px;
      font-weight: 600;
      color: var(--accent-amber);
      text-transform: uppercase;
      letter-spacing: 1px;
      margin-bottom: var(--space-2);
    }

    .work-card-title {
      font-size: 18px;
      font-weight: 700;
      margin-bottom: var(--space-3);
      line-height: 1.3;
    }

    .work-card-quote {
      font-size: 13px;
      color: var(--text-muted);
      line-height: 1.6;
      font-style: italic;
    }

    .work-nav {
      display: flex;
      justify-content: center;
      gap: var(--space-3);
      margin-top: var(--space-5);
    }

    /* ============ CTA BANNER ============ */
    .cta-banner {
      padding: var(--space-8) 0;
      background: linear-gradient(135deg, var(--bg-surface) 0%, var(--bg-base) 100%);
      border-top: 1px solid var(--border-light);
      text-align: center;
    }

    .cta-title {
      font-size: clamp(36px, 5vw, 64px);
      font-weight: 800;
      letter-spacing: -2px;
      margin-bottom: var(--space-4);
    }

    .cta-body {
      font-size: 18px;
      color: var(--text-secondary);
      max-width: 600px;
      margin: 0 auto var(--space-6);
      line-height: 1.7;
    }

    .cta-btn {
      display: inline-flex;
      align-items: center;
      gap: var(--space-3);
      background: var(--accent-blue);
      color: #fff;
      padding: 16px 36px;
      border-radius: var(--radius-sm);
      font-size: 16px;
      font-weight: 600;
      transition: all var(--transition);
      border: none;
      cursor: pointer;
    }

    .cta-btn:hover {
      background: var(--accent-blue-muted);
      transform: translateY(-2px);
      box-shadow: 0 15px 40px rgba(79, 143, 255, 0.35);
    }

    /* ============ HOW WE WORK ============ */
    .how-we-work {
      padding: var(--space-8) 0;
      background: var(--bg-base);
      border-top: 1px solid var(--border-light);
    }

    .how-we-work-grid {
      display: grid;
      grid-template-columns: 1fr;
      gap: var(--space-6);
      align-items: center;
    }

    @media (min-width: 1024px) {
      .how-we-work-grid {
        grid-template-columns: 1fr 1fr;
      }
    }

    .how-we-work-content .section-tag {
      text-align: left;
    }

    .how-we-work-title {
      font-size: clamp(32px, 4vw, 48px);
      font-weight: 800;
      letter-spacing: -1.5px;
      margin-bottom: var(--space-4);
      line-height: 1.1;
    }

    .how-we-work-body {
      font-size: 17px;
      color: var(--text-secondary);
      line-height: 1.8;
      margin-bottom: var(--space-5);
    }

    .how-we-work-visual {
      aspect-ratio: 1;
      background: linear-gradient(135deg, var(--bg-elevated) 0%, var(--bg-surface) 100%);
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      display: flex;
      align-items: center;
      justify-content: center;
      position: relative;
      overflow: hidden;
    }

    .how-we-work-visual::before {
      content: '';
      position: absolute;
      inset: 0;
      background: radial-gradient(circle at 30% 30%, rgba(79, 143, 255, 0.15) 0%, transparent 50%),
                  radial-gradient(circle at 70% 70%, rgba(255, 179, 71, 0.1) 0%, transparent 50%);
    }

    .how-we-work-visual-inner {
      position: relative;
      text-align: center;
      padding: var(--space-5);
    }

    .how-we-work-visual-inner svg {
      width: 80px;
      height: 80px;
      color: var(--accent-blue);
      margin-bottom: var(--space-4);
    }

    .how-we-work-visual-inner p {
      font-size: 14px;
      color: var(--text-muted);
    }

    /* ============ INSIGHTS ============ */
    .insights {
      padding: var(--space-8) 0;
      background: #080808;
      border-top: 1px solid var(--border-light);
    }

    .insights-grid {
      display: grid;
      grid-template-columns: 1fr;
      gap: var(--space-4);
    }

    @media (min-width: 640px) {
      .insights-grid {
        grid-template-columns: repeat(2, 1fr);
      }
    }

    @media (min-width: 1024px) {
      .insights-grid {
        grid-template-columns: repeat(4, 1fr);
      }
    }

    .insight-card {
      background: var(--bg-surface);
      border: 1px solid var(--border-light);
      border-radius: var(--radius-md);
      overflow: hidden;
      transition: all var(--transition);
    }

    .insight-card:hover {
      border-color: var(--accent-blue);
      transform: translateY(-2px);
    }

    .insight-card-image {
      aspect-ratio: 16/9;
      background: var(--bg-elevated);
      overflow: hidden;
    }

    .insight-card-image img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      filter: grayscale(30%) brightness(0.8);
      transition: all var(--transition);
    }

    .insight-card:hover .insight-card-image img {
      filter: grayscale(0%) brightness(0.9);
    }

    .insight-card-body {
      padding: var(--space-4);
    }

    .insight-card-type {
      font-size: 10px;
      font-weight: 700;
      color: var(--accent-blue);
      text-transform: uppercase;
      letter-spacing: 1px;
      margin-bottom: var(--space-2);
    }

    .insight-card-title {
      font-size: 14px;
      font-weight: 600;
      line-height: 1.4;
      margin-bottom: var(--space-3);
    }

    .insight-card-cta {
      font-size: 12px;
      font-weight: 600;
      color: var(--accent-blue);
      display: inline-flex;
      align-items: center;
      gap: var(--space-1);
    }

    .insight-card-cta svg {
      width: 12px;
      height: 12px;
      transition: transform var(--transition);
    }

    .insight-card:hover .insight-card-cta svg {
      transform: translateX(3px);
    }

    /* ============ PRINCIPLES ============ */
    .principles {
      padding: var(--space-8) 0;
      background: var(--bg-base);
      border-top: 1px solid var(--border-light);
    }

    .principles-grid {
      display: grid;
      grid-template-columns: 1fr;
      gap: var(--space-4);
    }

    @media (min-width: 640px) {
      .principles-grid {
        grid-template-columns: repeat(2, 1fr);
      }
    }

    @media (min-width: 1024px) {
      .principles-grid {
        grid-template-columns: repeat(4, 1fr);
      }
    }

    .principle-card {
      padding: var(--space-6);
      background: var(--bg-surface);
      border: 1px solid var(--border-light);
      border-radius: var(--radius-lg);
      transition: all var(--transition);
      position: relative;
      overflow: hidden;
    }

    .principle-card::before {
      content: '';
      position: absolute;
      top: 0;
      left: 0;
      right: 0;
      height: 3px;
      background: linear-gradient(90deg, var(--accent-blue), var(--accent-amber));
      opacity: 0;
      transition: opacity var(--transition);
    }

    .principle-card:hover {
      border-color: var(--accent-blue);
      transform: translateY(-4px);
    }

    .principle-card:hover::before {
      opacity: 1;
    }

    .principle-number {
      font-size: 48px;
      font-weight: 900;
      color: var(--bg-elevated);
      line-height: 1;
      margin-bottom: var(--space-3);
    }

    .principle-title {
      font-size: 18px;
      font-weight: 700;
      margin-bottom: var(--space-3);
    }

    .principle-desc {
      font-size: 14px;
      color: var(--text-muted);
      line-height: 1.7;
    }

    /* ============ FOOTER ============ */
    .footer {
      background: #050505;
      border-top: 1px solid var(--border-light);
      padding: var(--space-8) 0 var(--space-4);
    }

    .footer-ctas {
      display: grid;
      grid-template-columns: 1fr;
      gap: var(--space-4);
      margin-bottom: var(--space-7);
    }

    @media (min-width: 768px) {
      .footer-ctas {
        grid-template-columns: repeat(2, 1fr);
      }
    }

    .footer-cta {
      padding: var(--space-6);
      background: var(--bg-surface);
      border: 1px solid var(--border-light);
      border-radius: var(--radius-lg);
      text-align: center;
    }

    .footer-cta p {
      font-size: 16px;
      color: var(--text-secondary);
      margin-bottom: var(--space-4);
      line-height: 1.6;
    }

    .footer-btn {
      display: inline-flex;
      align-items: center;
      gap: var(--space-2);
      padding: 12px 24px;
      border-radius: var(--radius-sm);
      font-size: 14px;
      font-weight: 600;
      transition: all var(--transition);
      border: none;
      cursor: pointer;
    }

    .footer-btn-primary {
      background: var(--accent-blue);
      color: #fff;
    }

    .footer-btn-primary:hover {
      background: var(--accent-blue-muted);
      transform: translateY(-2px);
    }

    .footer-btn-secondary {
      background: transparent;
      border: 1px solid var(--border);
      color: var(--text-primary);
    }

    .footer-btn-secondary:hover {
      border-color: var(--accent-blue);
      color: var(--accent-blue);
    }

    .footer-links {
      display: flex;
      flex-wrap: wrap;
      justify-content: center;
      gap: var(--space-4);
      padding: var(--space-5) 0;
      border-top: 1px solid var(--border-light);
      border-bottom: 1px solid var(--border-light);
      margin-bottom: var(--space-4);
    }

    .footer-links a {
      font-size: 13px;
      font-weight: 500;
      color: var(--text-muted);
      transition: color var(--transition);
    }

    .footer-links a:hover {
      color: var(--text-primary);
    }

    .footer-bottom {
      display: flex;
      flex-wrap: wrap;
      justify-content: space-between;
      align-items: center;
      gap: var(--space-3);
    }

    .footer-legal {
      font-size: 12px;
      color: var(--text-muted);
    }

    .footer-legal-links {
      display: flex;
      gap: var(--space-4);
    }

    .footer-legal-links a {
      font-size: 12px;
      color: var(--text-muted);
      transition: color var(--transition);
    }

    .footer-legal-links a:hover {
      color: var(--text-primary);
    }

    /* ============ COOKIE BANNER ============ */
    .cookie-banner {
      position: fixed;
      bottom: 0;
      left: 0;
      right: 0;
      background: var(--bg-elevated);
      border-top: 1px solid var(--border);
      padding: var(--space-4) var(--space-5);
      z-index: 200;
      transform: translateY(100%);
      transition: transform var(--transition);
    }

    .cookie-banner.active {
      transform: translateY(0);
    }

    .cookie-inner {
      max-width: 1280px;
      margin: 0 auto;
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      justify-content: space-between;
      gap: var(--space-4);
    }

    .cookie-text {
      font-size: 13px;
      color: var(--text-secondary);
      flex: 1;
      min-width: 280px;
    }

    .cookie-text a {
      color: var(--accent-blue);
      text-decoration: underline;
    }

    .cookie-actions {
      display: flex;
      gap: var(--space-3);
      flex-wrap: wrap;
    }

    .cookie-btn {
      padding: 10px 20px;
      border-radius: var(--radius-sm);
      font-size: 13px;
      font-weight: 600;
      cursor: pointer;
      transition: all var(--transition);
      border: none;
    }

    .cookie-btn-accept {
      background: var(--accent-blue);
      color: #fff;
    }

    .cookie-btn-accept:hover {
      background: var(--accent-blue-muted);
    }

    .cookie-btn-decline {
      background: transparent;
      border: 1px solid var(--border);
      color: var(--text-primary);
    }

    .cookie-btn-decline:hover {
      border-color: var(--text-muted);
    }

    .cookie-btn-settings {
      background: transparent;
      border: 1px solid var(--border);
      color: var(--text-secondary);
    }

    .cookie-btn-settings:hover {
      border-color: var(--text-muted);
      color: var(--text-primary);
    }

    /* ============ ANIMATIONS ============ */
    @media (prefers-reduced-motion: no-preference) {
      .fade-in {
        animation: fadeIn 0.6s ease-out forwards;
      }

      @keyframes fadeIn {
        from {
          opacity: 0;
          transform: translateY(20px);
        }
        to {
          opacity: 1;
          transform: translateY(0);
        }
      }
    }

    /* ============ RESPONSIVE ============ */
    @media (max-width: 768px) {
      .container {
        padding: 0 var(--space-4);
      }

      .team-card {
        flex: 0 0 300px;
      }

      .work-card {
        flex: 0 0 320px;
      }

      .hero-title {
        letter-spacing: -1px;
      }

      .section-title {
        letter-spacing: -1px;
      }

      .how-we-work-grid {
        gap: var(--space-5);
      }
    }

    @media (max-width: 480px) {
      .team-card {
        flex: 0 0 280px;
      }

      .work-card {
        flex: 0 0 280px;
      }

      .region-tabs {
        gap: var(--space-2);
      }

      .region-tab {
        padding: 8px 14px;
        font-size: 13px;
      }
    }

    /* ============ PLACEHOLDER IMAGES ============ */
    .placeholder-img {
      width: 100%;
      height: 100%;
      display: flex;
      align-items: center;
      justify-content: center;
      background: linear-gradient(135deg, var(--bg-elevated) 0%, var(--bg-surface) 100%);
      color: var(--text-muted);
      font-size: 12px;
    }

    .placeholder-img svg {
      width: 32px;
      height: 32px;
      opacity: 0.5;
    }
  </style>
</head>
